-- Auto-generated by scripts/compile_channel_macro.py from config/channels.yaml
{% macro map_channel(source_col, medium_col) -%}
CASE
    WHEN {{ source_col }} = '(direct)' AND {{ medium_col }} = '(none)' THEN 'direct'
    WHEN {{ medium_col }} = 'organic' THEN 'organic_search'
    WHEN {{ source_col }} = 'google' AND {{ medium_col }} IN ('cpc', 'ppc') THEN 'paid_search'
    WHEN {{ medium_col }} IN ('display', 'cpm') THEN 'display'
    WHEN {{ medium_col }} = 'email' THEN 'email'
    WHEN {{ medium_col }} = 'affiliate' THEN 'affiliate'
    WHEN {{ medium_col }} IN ('paid-social', 'paidsocial') THEN 'paid_social'
    WHEN {{ medium_col }} IN ('social', 'social-network', 'social-media') THEN 'social_organic'
    WHEN {{ medium_col }} = 'referral' THEN 'referral'
    ELSE 'unassigned'
END
{%- endmacro %}
